import { DeliveredAlert } from "../domain/notification";
import { OrderEventKind } from "../domain/order";
import { MqpubClient } from "../messaging/mqpubClient";
import { decodePayload } from "../messaging/payloadCodec";
import { shouldResend } from "../service/resendPolicy";
import { CustomerRepository } from "../repository/customerRepository";
import { DeliveryLogRepository } from "../repository/deliveryLogRepository";
import { SmsGateway } from "./smsGateway";
import { renderAlert } from "./templates";

export interface DrainResult {
  read: number;
  delivered: DeliveredAlert[];
  failed: { orderNo: string; kind: OrderEventKind; reason: string }[];
}

/**
 * 알림 토픽 소비자. 마지막으로 읽은 위치 다음부터 읽어 문자를 보낸다.
 * 같은 키가 다시 전달되면(재처리·재기동) 두 번 보내지 않는다.
 */
export class AlertConsumer {
  private nextOffset = 0;
  private readonly handledKeys = new Set<string>();

  constructor(
    private readonly client: MqpubClient,
    private readonly topic: string,
    private readonly customers: CustomerRepository,
    private readonly gateway: SmsGateway,
    private readonly log: DeliveryLogRepository,
    private readonly senderId: string,
    private readonly limit: number,
  ) {}

  position(): number {
    return this.nextOffset;
  }

  drain(runId: number): DrainResult {
    const rows = this.client.consume(this.topic, this.nextOffset).slice(0, this.limit);
    const result: DrainResult = { read: rows.length, delivered: [], failed: [] };
    for (const row of rows) {
      this.nextOffset = row.offset + 1;
      if (this.handledKeys.has(row.key)) continue;
      this.handledKeys.add(row.key);

      const n = decodePayload(row.payload);
      if (!n) {
        result.failed.push({ orderNo: "?", kind: "PAID", reason: "bad-payload" });
        continue;
      }
      const customer = this.customers.find(n.customerId);
      if (!customer) {
        result.failed.push({ orderNo: n.orderNo, kind: n.kind, reason: "unknown-customer" });
        continue;
      }
      const receipt = this.gateway.send(this.senderId, customer.phone, renderAlert(n.kind, customer.name, n.orderNo));
      if (!receipt.ok) {
        const reason = receipt.reason ?? "sms-failed";
        result.failed.push({ orderNo: n.orderNo, kind: n.kind, reason });
        if (shouldResend(reason)) this.handledKeys.delete(row.key); // 다음 회차에 같은 키로 다시 온다
        continue;
      }
      const d: DeliveredAlert = {
        runId,
        orderNo: n.orderNo,
        customerId: n.customerId,
        kind: n.kind,
        phone: customer.phone,
        receiptId: receipt.receiptId ?? "",
      };
      this.log.append(d);
      result.delivered.push(d);
    }
    return result;
  }
}
import { createHash } from "crypto";
import { normalizeMobile } from "../util/format";

export interface SmsReceipt {
  ok: boolean;
  receiptId?: string;
  reason?: string;
}

export interface SmsGateway {
  send(from: string, to: string, text: string): SmsReceipt;
}

/**
 * 문자 대행사 실패 응답 코드
 *   invalid-number  수신 번호 형식 오류(우리 쪽 검증)
 *   empty-body      본문 없음(우리 쪽 검증)
 *   E-THROTTLE      초당 발송 한도 초과
 *   E-CARRIER       통신사 일시 반려
 *   E-SPAM          통신사 스팸 차단(수신자 설정)
 */
export type SmsFailure = "invalid-number" | "empty-body" | "E-THROTTLE" | "E-CARRIER" | "E-SPAM";

/**
 * 문자 대행사 모의 게이트웨이 — 받은 문자를 번호별 수신함에 쌓는다.
 * faults: 번호(숫자 11자리)별로 다음 발송 시도들에 차례대로 돌려줄 실패 코드.
 */
export class InMemorySmsGateway implements SmsGateway {
  private readonly inboxes = new Map<string, string[]>();
  private readonly tries = new Map<string, number>();
  private readonly faults = new Map<string, string[]>();
  private sent = 0;

  constructor(faults: Record<string, string[]> = {}) {
    for (const [raw, codes] of Object.entries(faults)) {
      const number = normalizeMobile(raw);
      if (number) this.faults.set(number, [...codes]);
    }
  }

  send(from: string, to: string, text: string): SmsReceipt {
    const number = normalizeMobile(to);
    if (!number) return { ok: false, reason: "invalid-number" };
    if (text.length === 0) return { ok: false, reason: "empty-body" };
    this.tries.set(number, (this.tries.get(number) ?? 0) + 1);
    const fault = this.faults.get(number)?.shift();
    if (fault) return { ok: false, reason: fault };
    this.sent++;
    const list = this.inboxes.get(number) ?? [];
    list.push(text);
    this.inboxes.set(number, list);
    const receiptId = createHash("sha1").update(`${from}|${number}|${this.sent}|${text}`).digest("hex").slice(0, 12);
    return { ok: true, receiptId };
  }

  inbox(phone: string): string[] {
    const number = normalizeMobile(phone);
    return number ? [...(this.inboxes.get(number) ?? [])] : [];
  }

  /** 대행사에 넘긴 발송 요청 수(성공·실패 포함) */
  attempts(phone: string): number {
    const number = normalizeMobile(phone);
    return number ? this.tries.get(number) ?? 0 : 0;
  }
}
import { KIND_LABEL } from "../domain/notification";
import { OrderEventKind } from "../domain/order";
import { clip } from "../util/format";

const SMS_WIDTH = 80;

export function renderAlert(kind: OrderEventKind, customerName: string, orderNo: string): string {
  const greeting = `[한빛페이] ${customerName}님, 주문 ${orderNo}`;
  const tail: Record<OrderEventKind, string> = {
    PAID: "결제가 완료되었습니다.",
    SHIPPED: "상품이 출발했습니다.",
    DELIVERED: "배송이 완료되었습니다.",
  };
  return clip(`${greeting} ${KIND_LABEL[kind]} — ${tail[kind]}`, SMS_WIDTH);
}
import { Notification } from "../domain/notification";
import { messageKey } from "./keys";
import { MqpubClient, PublishResult, WireMessage } from "./mqpubClient";
import { encodePayload } from "./payloadCodec";

/** 발송 회차 하나의 알림을 한 배치로 발행한다(회차 단위 순서·원자성). */
export class AlertPublisher {
  constructor(
    private readonly client: MqpubClient,
    private readonly topic: string,
    private readonly keyNamespace: string,
  ) {}

  toWire(n: Notification): WireMessage {
    return { key: messageKey(this.keyNamespace, n.kind, n.orderNo), payload: encodePayload(n) };
  }

  publishRun(notifications: Notification[]): PublishResult {
    return this.client.publish(this.topic, notifications.map((n) => this.toWire(n)));
  }
}
import { createHash } from "crypto";
import { OrderEventKind } from "../domain/order";

const KIND_CODE: Record<OrderEventKind, string> = {
  PAID: "paid",
  SHIPPED: "ship",
  DELIVERED: "dlvd",
};

/**
 * 알림 메시지 키 — `<전체 키의 해시 16자>:<네임스페이스>.<이벤트>.<업무 식별자>`.
 * mqpub 는 한 배치 안에서 키의 앞 16바이트가 같은 메시지를 첫 것만 남기고 조용히 버린다.
 * 공통 접두로 시작하는 키는 서로 덮이므로, 메시지마다 다른 결정적 해시를 맨 앞에 둔다.
 * 소비 측은 이 키로 이미 처리한 메시지를 걸러낸다(재전달 대비) — 같은 알림은 늘 같은 키.
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const logical = `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
  const head = createHash("sha1").update(logical).digest("hex").slice(0, 16);
  return `${head}:${logical}`;
}

export function kindFromCode(code: string): OrderEventKind | undefined {
  return (Object.keys(KIND_CODE) as OrderEventKind[]).find((k) => KIND_CODE[k] === code);
}
import { spawnSync } from "child_process";

export interface WireMessage {
  key: string;
  payload: string;
}

export interface PublishResult {
  accepted: number;
  batch: number;
}

export interface ConsumedMessage {
  offset: number;
  key: string;
  payload: string;
}

export class MqpubError extends Error {
  constructor(readonly code: string, readonly exitStatus: number | null) {
    super(`mqpub ${code} (exit ${exitStatus})`);
  }
}

/** 사내 메시지 발행 CLI(mqpub 3.x) 래퍼 */
export class MqpubClient {
  constructor(private readonly bin: string, private readonly spoolDir: string) {}

  private run(args: string[], input?: string): string {
    const r = spawnSync(this.bin, args, {
      input,
      encoding: "utf8",
      env: { ...process.env, MQPUB_SPOOL: this.spoolDir },
    });
    if (r.error) throw r.error;
    if (r.status !== 0) {
      const code = /E\d+/.exec(r.stderr)?.[0] ?? "E?";
      throw new MqpubError(code, r.status);
    }
    return r.stdout;
  }

  /** 메시지들을 한 배치로 발행한다. */
  publish(topic: string, messages: WireMessage[]): PublishResult {
    if (messages.length === 0) return { accepted: 0, batch: 0 };
    const body = messages.map((m) => `${m.key}\t${m.payload}`).join("\n") + "\n";
    const out = this.run(["publish", "-t", topic], body);
    const m = /^accepted (\d+) batch (\d+)$/m.exec(out);
    if (!m) throw new MqpubError("unparsed-output", 0);
    return { accepted: Number(m[1]), batch: Number(m[2]) };
  }

  /** offset 부터 끝까지 읽는다. */
  consume(topic: string, fromOffset: number): ConsumedMessage[] {
    const out = this.run(["consume", "-t", topic, "-o", String(fromOffset)]);
    const rows: ConsumedMessage[] = [];
    for (const line of out.split("\n")) {
      if (line === "") continue;
      const [off, key, ...rest] = line.split("\t");
      rows.push({ offset: Number(off), key, payload: rest.join("\t") });
    }
    return rows;
  }
}
import { Notification } from "../domain/notification";
import { isEventKind } from "../domain/order";

const VERSION = 2;
const MAX_PAYLOAD = 900;

interface WirePayload {
  v: number;
  o: string;
  c: string;
  k: string;
}

/** 탭·개행·제어문자는 와이어 형식(<key>TAB<payload>)을 깨므로 제거한다. */
function scrub(s: string): string {
  return s.replace(/[\u0000-\u001f\u007f]/g, "");
}

export function encodePayload(n: Notification): string {
  const body: WirePayload = { v: VERSION, o: scrub(n.orderNo), c: scrub(n.customerId), k: n.kind };
  const json = JSON.stringify(body);
  if (json.length > MAX_PAYLOAD) throw new Error("payload too large");
  return json;
}

export function decodePayload(raw: string): Notification | null {
  let body: Partial<WirePayload>;
  try {
    body = JSON.parse(raw) as Partial<WirePayload>;
  } catch {
    return null;
  }
  if (body.v !== VERSION && body.v !== 1) return null;
  if (typeof body.o !== "string" || typeof body.c !== "string" || !isEventKind(body.k)) return null;
  return { orderNo: body.o, customerId: body.c, kind: body.k };
}
import { join } from "path";

export interface AppConfig {
  /** 고객 알림 토픽 */
  topic: string;
  /** 사내 메시지 키 네임스페이스 */
  keyNamespace: string;
  /** mqpub 실행 파일 경로 */
  mqpubBin: string;
  /** mqpub 스풀 디렉토리(MQPUB_SPOOL) */
  spoolDir: string;
  /** 문자 발신 번호 */
  senderId: string;
  /** 한 번에 읽어 올 최대 메시지 수 */
  drainLimit: number;
  /** 모의 문자 게이트웨이 장애 주입(개발·스테이징): 번호별로 차례대로 돌려줄 실패 코드 */
  smsFaults: Record<string, string[]>;
}

export function loadConfig(overrides: Partial<AppConfig> = {}): AppConfig {
  const env = process.env;
  const base: AppConfig = {
    topic: env.ALERTS_TOPIC ?? "alerts.order",
    keyNamespace: env.ALERTS_KEY_NS ?? "ntf",
    mqpubBin: env.MQPUB_BIN ?? join(process.cwd(), "vendor", "bin", "mqpub"),
    spoolDir: env.MQPUB_SPOOL ?? join(process.cwd(), "var", "spool"),
    senderId: "1588-0000",
    drainLimit: 500,
    smsFaults: {},
  };
  return { ...base, ...overrides };
}

